package filemanager

import "github.com/washsky/mygpt-test/internal/ui"

const previewPage = `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>文件预览</title>` + ui.Head + `<style>main{max-width:1180px;margin:24px auto;padding:0 24px}.card{padding:24px}.preview-actions{display:flex;gap:10px;flex-wrap:wrap;margin:18px 0}h1{overflow-wrap:anywhere}#preview-note{color:var(--muted)}</style></head><body>` + ui.Nav + `<main><div class="workspace-hero"><div><div class="eyebrow">资料库 / 文件预览</div><h1 id="name">正在读取文件…</h1><p id="meta"></p></div><a class="workspace-link" href="/files">返回文件资料</a></div><section class="card"><div id="actions" class="preview-actions"></div><p id="preview-note" role="status">加载中…</p><iframe id="viewer" class="preview-frame" title="文件内容预览" hidden></iframe></section></main>` + ui.Foot + `<script>
(async()=>{const id=location.pathname.split('/').pop(),note=document.getElementById('preview-note');try{const response=await fetch('/api/files/'+encodeURIComponent(id)+'/info');if(!response.ok)throw Error(response.status===404?'文件已删除或不存在。':'无法加载文件，请刷新重试。');const file=await response.json();document.getElementById('name').textContent=file.name;document.getElementById('meta').textContent=(file.size/1024).toFixed(1)+' KB · '+new Date(file.uploaded_at).toLocaleString();const actions=document.getElementById('actions');function link(text,href){const a=document.createElement('a');a.className='workspace-link';a.textContent=text;a.href=href;actions.append(a)}link('下载原文件','/api/files/'+encodeURIComponent(id));{const share=document.createElement('button');share.textContent='发送到共享';share.hidden=!window.workspaceOptions.enable_clipboard;window.addEventListener('workspace-options',event=>{share.hidden=!event.detail.enable_clipboard});share.onclick=async()=>{const ok=await window.workspaceShareFile?.(file);note.textContent=ok?'附件已加入共享历史。':'发送失败，请检查共享设置。'};actions.append(share)}if(file.association?.id&&['post','reply'].includes(file.association.type)){const params=new URLSearchParams({related_type:file.association.type,related_id:file.association.id});link('返回来源'+(file.association.type==='post'?'笔记':'回复'),'/#'+file.association.type+'/'+encodeURIComponent(file.association.id));link('同一来源的附件','/files?'+params)}const image=['image/png','image/jpeg','image/gif','image/webp'].includes(file.content_type),pdf=/\.pdf$/i.test(file.name)&&file.content_type==='application/pdf',text=/\.(txt|md|markdown|json|csv|log)$/i.test(file.name)&&file.size<=1048576;if(image||pdf||text){const frame=document.getElementById('viewer');frame.src='/api/files/'+encodeURIComponent(id)+'/preview';frame.hidden=false;note.textContent='下方为文件预览。若格式不支持或浏览器无法显示，请下载原文件查看。'}else{note.textContent='此格式或大小暂不支持在线预览，请下载原文件查看。'}}catch(error){document.getElementById('name').textContent='无法打开文件';note.textContent=error.message}})();
</script></body></html>`
